mapper.select:
SELECT s.id, s.scale_name, s.scale_category_id, s.current_version_id, s.status, s.allow_repeat, s.cool_minutes, s.time_limit, s.anonymous, s.created_time, s.updated_time, s.deleted AS deleted_flag, sc.category_name AS scale_category_name, sv.version_no AS current_version_no, (SELECT COUNT(*) FROM scale_question q WHERE q.scale_version_id = s.current_version_id AND q.deleted = 0) AS question_count, (SELECT COUNT(*) FROM scale_dimension d WHERE d.scale_version_id = s.current_version_id AND d.deleted = 0) AS dimension_count FROM scale s LEFT JOIN scale_category sc ON sc.id = s.scale_category_id AND sc.deleted = 0 LEFT JOIN scale_version sv ON sv.id = s.current_version_id AND sv.deleted = 0
AND s.scale_name LIKE CONCAT('%', #{scaleName}, '%')
AND s.scale_category_id = #{scaleCategoryId}
AND s.status = #{status}
AND s.deleted = #{deletedFlag}
ORDER BY s.created_time DESC, s.id DESC
